USE CONSULTAS;

CREATE TABLE IF NOT EXISTS Products(
ProductID int not null,
ProductName VARCHAR(50),
SupplierID int,
CategoryID int,
Unit VARCHAR(80),
Price DECIMAL(10,2),
CustomerID INT,
PRIMARY KEY(ProductID),
FOREIGN KEY(CustomerID) REFERENCES Customers(CustomerID)
);



SELECT COUNT(*) FROM Products;

   SELECT COUNT(*) FROM Customers;
   
      SELECT * FROM Products LIMIT 10;
   SELECT * FROM Customers LIMIT 10;
      
      USE CONSULTAS;

-- 1) Clientes con Address NULL
SELECT * FROM Customers
WHERE Address IS NULL;

-- 2) Clientes con Address distinto de NULL
SELECT * FROM Customers
WHERE Address IS NOT NULL;

-- 3) Producto con el precio más barato
SELECT ProductName, Price
FROM Products
WHERE Price = (SELECT MIN(Price) FROM Products);

-- 4) Producto más caro y su precio
SELECT ProductName, Price
FROM Products
WHERE Price = (SELECT MAX(Price) FROM Products);

-- 5) Número de productos
SELECT COUNT(*) AS NumProductos
FROM Products;

-- 6) Media de precio de todos los productos
SELECT AVG(Price) AS PrecioMedio
FROM Products;

-- 7) Clientes cuyo nombre empieza por 'a'
SELECT CustomerName
FROM Customers
WHERE CustomerName LIKE 'a%';

-- 8) Clientes cuyo nombre termina por 'a'
SELECT CustomerName
FROM Customers
WHERE CustomerName LIKE '%a';

-- 9) Clientes con "or" en cualquier posición
SELECT CustomerName
FROM Customers
WHERE CustomerName LIKE '%or%';

-- 10) Clientes con 'r' en la segunda posición
SELECT CustomerName
FROM Customers
WHERE CustomerName LIKE '_r%';

-- 11) Clientes que empiezan por 'a' y tienen al menos 3 caracteres
SELECT CustomerName
FROM Customers
WHERE CustomerName LIKE 'a__%';

-- 12) Clientes cuyo nombre NO empieza por 'a'
SELECT CustomerName
FROM Customers
WHERE CustomerName NOT LIKE 'a%';

-- 13) Clientes en Germany, France o UK
SELECT *
FROM Customers
WHERE Country IN ('Germany', 'France', 'UK');

-- 14) Clientes que NO están en Germany, France o UK
SELECT *
FROM Customers
WHERE Country NOT IN ('Germany', 'France', 'UK');

-- 15) Descansa y respira un poco :)

-- 16) Productos con precio entre 10 y 20
SELECT *
FROM Products
WHERE Price BETWEEN 10 AND 20;

-- 17) Precio entre 10 y 20 y categoría distinta de 1, 2 y 3
SELECT *
FROM Products
WHERE Price BETWEEN 10 AND 20
  AND CategoryID NOT IN (1, 2, 3);

-- 18) Productos entre "Carnarvon Tigers" y "Mozzarella di Giovanni"
SELECT *
FROM Products
WHERE ProductName BETWEEN 'Carnarvon Tigers' AND 'Mozzarella di Giovanni'
ORDER BY ProductName;

-- 19) Consulta con 2 alias
SELECT CustomerID AS ID, CustomerName AS Cliente
FROM Customers;

-- 20-21) Descansa un poco y respira profundo :)

-- 22) Número de clientes en cada país
SELECT Country, COUNT(*) AS NumClientes
FROM Customers
GROUP BY Country
ORDER BY NumClientes DESC;